def count_ortho_same_neighbors(grid, r, c, color, rows, cols):
    """Count orthogonal neighbors of same color"""
    count = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
